type AttachmentPhase = 'local' | 'uploading' | 'ready' | 'error';
type StreamPhase = 'pending' | 'streaming' | 'complete' | 'stopped' | 'failed';

interface ComposerDraft {
  accountId: string;
  conversationId: string;
  text: string;
  revision: number;
  savedAt: number;
  attachmentLocalIds: string[];
}

interface ComposerInteractionState {
  isComposing: boolean;
}

interface AttachmentDraft {
  localId: string;
  phase: AttachmentPhase;
  assetId: string | null;
  error: string | null;
}

interface PendingSend {
  conversationId: string;
  commandId: string;
  clientMessageId: string;
  draftRevision: number;
  phase: 'sending' | 'acknowledged' | 'uncertain';
}

interface StreamMessage {
  conversationId: string;
  commandId: string;
  clientMessageId: string;
  messageId: string;
  streamId: string;
  lastSequence: number;
  text: string;
  phase: StreamPhase;
}

interface TurnSnapshot extends StreamMessage {
  updatedAt: number;
}
